-- Apply once after migration-v2.sql. Existing business records are retained.
CREATE TABLE schema_version (version_no INT PRIMARY KEY, installed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO schema_version(version_no) VALUES(1),(2);
CREATE TABLE repair_rule (rule_id BIGINT PRIMARY KEY AUTO_INCREMENT, accept_minutes INT NOT NULL, normal_minutes INT NOT NULL, urgent_minutes INT NOT NULL, confirm_days INT NOT NULL, edit_days INT NOT NULL, max_rework_count INT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO repair_rule(accept_minutes,normal_minutes,urgent_minutes,confirm_days,edit_days) VALUES(120,1440,360,7,7);
ALTER TABLE repair_order ADD COLUMN rule_id BIGINT NOT NULL DEFAULT 1, ADD COLUMN archived_at DATETIME NULL, ADD COLUMN archive_reason VARCHAR(100) NULL, ADD FOREIGN KEY(rule_id) REFERENCES repair_rule(rule_id);
ALTER TABLE repair_dispatch ADD COLUMN accept_deadline DATETIME NULL, ADD COLUMN repair_deadline DATETIME NULL;
UPDATE repair_dispatch SET accept_deadline=DATE_ADD(created_at,INTERVAL 120 MINUTE),repair_deadline=DATE_ADD(COALESCE(decided_at,created_at),INTERVAL 1440 MINUTE);
CREATE TABLE repairer_profile(repairer_user_id BIGINT PRIMARY KEY, on_duty TINYINT NOT NULL DEFAULT 1, max_active_orders INT NULL, FOREIGN KEY(repairer_user_id) REFERENCES sys_user(user_id));
CREATE TABLE repairer_work_type(repairer_user_id BIGINT NOT NULL,work_type_id BIGINT NOT NULL,PRIMARY KEY(repairer_user_id,work_type_id),FOREIGN KEY(repairer_user_id) REFERENCES sys_user(user_id),FOREIGN KEY(work_type_id) REFERENCES repair_work_type(work_type_id));
CREATE TABLE repairer_building_scope(repairer_user_id BIGINT NOT NULL,building_id BIGINT NOT NULL,PRIMARY KEY(repairer_user_id,building_id),FOREIGN KEY(repairer_user_id) REFERENCES sys_user(user_id),FOREIGN KEY(building_id) REFERENCES building(building_id));
INSERT INTO repairer_profile(repairer_user_id) SELECT user_id FROM sys_user WHERE role_code='REPAIRER';
CREATE TABLE repair_submission_version(version_id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,title VARCHAR(120) NOT NULL,description TEXT NOT NULL,category_id BIGINT NOT NULL,submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES repair_order(order_id));
CREATE TABLE repair_confirmation(order_id BIGINT PRIMARY KEY,confirmation_mode VARCHAR(20) NOT NULL,confirmed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES repair_order(order_id));
CREATE TABLE repair_exception(exception_id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,dispatch_id BIGINT NULL,exception_type VARCHAR(30) NOT NULL,reason VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES repair_order(order_id),FOREIGN KEY(dispatch_id) REFERENCES repair_dispatch(dispatch_id));
CREATE TABLE stay_building_rule(batch_id BIGINT NOT NULL,building_id BIGINT NOT NULL,application_deadline DATETIME NOT NULL,auto_lock TINYINT NOT NULL DEFAULT 0,published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(batch_id,building_id),FOREIGN KEY(batch_id) REFERENCES stay_batch(batch_id),FOREIGN KEY(building_id) REFERENCES building(building_id));
CREATE TABLE stay_version(version_id BIGINT PRIMARY KEY AUTO_INCREMENT,application_id BIGINT NOT NULL,reason VARCHAR(500) NOT NULL,saved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,submitted_at DATETIME NULL,FOREIGN KEY(application_id) REFERENCES stay_application(application_id));
CREATE TABLE stay_date_range(range_id BIGINT PRIMARY KEY AUTO_INCREMENT,version_id BIGINT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,FOREIGN KEY(version_id) REFERENCES stay_version(version_id),CHECK(end_date>=start_date));
ALTER TABLE stay_application ADD COLUMN building_id BIGINT NULL,ADD COLUMN source VARCHAR(30) NOT NULL DEFAULT 'NORMAL',ADD COLUMN resubmit_deadline DATETIME NULL,ADD COLUMN archived_at DATETIME NULL,ADD COLUMN archive_reason VARCHAR(100) NULL;
UPDATE stay_application a JOIN accommodation_assignment x ON x.student_user_id=a.student_user_id JOIN bed bd ON bd.bed_id=x.bed_id JOIN dorm_room r ON r.room_id=bd.room_id SET a.building_id=r.building_id WHERE x.check_out_date IS NULL;
INSERT INTO stay_version(application_id,reason,submitted_at) SELECT application_id,COALESCE(reason,''),CASE WHEN current_status='DRAFT' THEN NULL ELSE updated_at END FROM stay_application;
INSERT INTO stay_date_range(version_id,start_date,end_date) SELECT v.version_id,a.start_date,a.end_date FROM stay_application a JOIN stay_version v ON v.application_id=a.application_id;
ALTER TABLE stay_application DROP COLUMN start_date,DROP COLUMN end_date,DROP COLUMN reason;
CREATE TABLE stay_review(review_id BIGINT PRIMARY KEY AUTO_INCREMENT,application_id BIGINT NOT NULL,version_id BIGINT NOT NULL,reviewer_user_id BIGINT NOT NULL,result VARCHAR(20) NOT NULL,reason VARCHAR(500),reviewed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES stay_application(application_id),FOREIGN KEY(version_id) REFERENCES stay_version(version_id),FOREIGN KEY(reviewer_user_id) REFERENCES sys_user(user_id));
ALTER TABLE site_message ADD COLUMN publisher_user_id BIGINT NULL,ADD COLUMN publish_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ADD COLUMN delivered_at DATETIME NULL;
CREATE TABLE message_target(message_id BIGINT NOT NULL,user_id BIGINT NOT NULL,PRIMARY KEY(message_id,user_id),FOREIGN KEY(message_id) REFERENCES site_message(message_id),FOREIGN KEY(user_id) REFERENCES sys_user(user_id));
INSERT IGNORE INTO message_receipt(message_id,user_id) SELECT m.message_id,u.user_id FROM site_message m JOIN sys_user u ON m.target_role='ALL' OR m.target_role=u.role_code;
UPDATE site_message SET delivered_at=created_at;
CREATE TABLE file_resource(file_id BIGINT PRIMARY KEY AUTO_INCREMENT,uploader_user_id BIGINT NOT NULL,original_name VARCHAR(255) NOT NULL,storage_name VARCHAR(80) NOT NULL UNIQUE,content_type VARCHAR(80) NOT NULL,size_bytes BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(uploader_user_id) REFERENCES sys_user(user_id));
CREATE TABLE repair_attachment(order_id BIGINT NOT NULL,file_id BIGINT NOT NULL,purpose VARCHAR(20) NOT NULL,PRIMARY KEY(order_id,file_id),FOREIGN KEY(order_id) REFERENCES repair_order(order_id),FOREIGN KEY(file_id) REFERENCES file_resource(file_id));
CREATE TABLE repair_delay_attachment(request_id BIGINT NOT NULL,file_id BIGINT NOT NULL,PRIMARY KEY(request_id,file_id),FOREIGN KEY(request_id) REFERENCES repair_delay_request(request_id),FOREIGN KEY(file_id) REFERENCES file_resource(file_id));
CREATE TABLE login_log(log_id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NULL,account VARCHAR(60),success TINYINT NOT NULL,occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE OR REPLACE VIEW v_accommodation_current AS SELECT a.assignment_id,a.student_user_id,u.real_name student_name,u.phone,b.building_id,b.building_name,r.room_id,r.room_no,bd.bed_id,bd.bed_no,a.check_in_date,a.check_out_date FROM accommodation_assignment a JOIN sys_user u ON u.user_id=a.student_user_id JOIN bed bd ON bd.bed_id=a.bed_id JOIN dorm_room r ON r.room_id=bd.room_id JOIN building b ON b.building_id=r.building_id WHERE a.check_in_date<=CURRENT_DATE() AND (a.check_out_date IS NULL OR CURRENT_DATE()<a.check_out_date);
CREATE OR REPLACE VIEW v_repair_order_dashboard AS SELECT ro.*,u.real_name student_name,r.building_id,r.room_no,b.building_name,c.category_name,c.work_type_id,w.work_type_name,rd.dispatch_id,rd.repairer_user_id,ru.real_name repairer_name,rd.accept_deadline,rd.repair_deadline,rr.result_text,ev.score,ev.comment,(SELECT COUNT(*) FROM repair_dispatch x WHERE x.order_id=ro.order_id AND x.dispatch_status='REJECTED') reject_count,(SELECT COUNT(*) FROM repair_dispatch x WHERE x.order_id=ro.order_id AND x.dispatch_status='TIMEOUT') accept_timeout_count,(SELECT COUNT(*) FROM repair_exception x WHERE x.order_id=ro.order_id AND x.exception_type='REPAIR_TIMEOUT') repair_timeout_count FROM repair_order ro JOIN sys_user u ON u.user_id=ro.student_user_id JOIN dorm_room r ON r.room_id=ro.room_id JOIN building b ON b.building_id=r.building_id LEFT JOIN fault_category c ON c.category_id=ro.category_id LEFT JOIN repair_work_type w ON w.work_type_id=c.work_type_id LEFT JOIN repair_dispatch rd ON rd.dispatch_id=(SELECT MAX(x.dispatch_id) FROM repair_dispatch x WHERE x.order_id=ro.order_id AND x.dispatch_status IN ('PENDING','ACCEPTED')) LEFT JOIN sys_user ru ON ru.user_id=rd.repairer_user_id LEFT JOIN repair_result rr ON rr.order_id=ro.order_id LEFT JOIN repair_evaluation ev ON ev.order_id=ro.order_id;
CREATE OR REPLACE VIEW v_stay_application AS SELECT a.*,u.real_name student_name,b.batch_name,bl.building_name,v.version_id,v.reason,v.submitted_at,(SELECT MIN(d.start_date) FROM stay_date_range d WHERE d.version_id=v.version_id) start_date,(SELECT MAX(d.end_date) FROM stay_date_range d WHERE d.version_id=v.version_id) end_date FROM stay_application a JOIN sys_user u ON u.user_id=a.student_user_id JOIN stay_batch b ON b.batch_id=a.batch_id LEFT JOIN building bl ON bl.building_id=a.building_id LEFT JOIN stay_version v ON v.version_id=(SELECT MAX(x.version_id) FROM stay_version x WHERE x.application_id=a.application_id AND x.submitted_at IS NOT NULL);
CREATE INDEX idx_repair_student_status ON repair_order(student_user_id,current_status);
CREATE INDEX idx_dispatch_worker_status ON repair_dispatch(repairer_user_id,dispatch_status);
CREATE INDEX idx_stay_building_status ON stay_application(building_id,current_status);
INSERT INTO schema_version(version_no) VALUES(3);
